cendants\":{\"link\":{\"textAlign\":\"center\",\"background\":{\"color\":\"rgba(var(--kubio-color-6),0.2)\"},\"typography\":{\"family\":\"Poppins\",\"margin\":{\"top\":\"\",\"bottom\":\"2rem\"},\"size\":{\"unit\":\"px\",\"value\":\"14\"},\"weight\":300,\"lineHeight\":{\"value\":\"1\",\"unit\":\"\"},\"transform\":\"uppercase\",\"letterSpacing\":{\"value\":\"1\",\"unit\":\"px\"},\"color\":\"rgba(var(--kubio-color-5),1)\"},\"border\":{\"top\":{\"style\":\"solid\",\"width\":{\"value\":1,\"unit\":\"px\"},\"radius\":{\"right\":{\"value\":0,\"unit\":\"px\"},\"left\":{\"value\":0,\"unit\":\"px\"}},\"color\":\"rgba(var(--kubio-color-5),1)\"},\"bottom\":{\"style\":\"solid\",\"width\":{\"value\":1,\"unit\":\"px\"},\"radius\":{\"right\":{\"value\":0,\"unit\":\"px\"},\"left\":{\"value\":0,\"unit\":\"px\"}},\"color\":\"rgba(var(--kubio-color-5),1)\"},\"right\":{\"style\":\"solid\",\"width\":{\"value\":1,\"unit\":\"px\"},\"color\":\"rgba(var(--kubio-color-5),1)\"},\"left\":{\"style\":\"solid\",\"width\":{\"value\":1,\"unit\":\"px\"},\"color\":\"rgba(var(--kubio-color-5),1)\"}},\"padding\":{\"top\":{\"unit\":\"px\",\"value\":20},\"bottom\":{\"unit\":\"px\",\"value\":20},\"left\":{\"unit\":\"px\",\"value\":40},\"right\":{\"unit\":\"px\",\"value\":40}},\"states\":{\"hover\":{\"border\":{\"top\":{\"color\":\"rgba(var(--kubio-color-5),1)\"},\"right\":{\"color\":\"rgba(var(--kubio-color-5),1)\"},\"bottom\":{\"color\":\"rgba(var(--kubio-color-5),1)\"},\"left\":{\"color\":\"rgba(var(--kubio-color-5),1)\"}},\"typography\":{\"color\":\"rgba(var(--kubio-color-6),1)\"},\"background\":{\"color\":\"rgba(var(--kubio-color-5),1)\"}}}},\"icon\":{\"size\":{\"unit\":\"px\",\"value\":\"14\"},\"margin\":{\"left\":{\"value\":10,\"unit\":\"px\"},\"right\":{\"value\":0,\"unit\":\"px\"}}}}},\"hash\":\"k5udrZn8B\"},\"link\":{\"value\":\"#contact\",\"typeOpenLink\":\"sameWindow\",\"noFollow\":false,\"lightboxMedia\":\"\"},\"preserveSpace\":{\"text\":false},\"icon\":{\"name\":\"font-awesome/arrow-right\"}} -