es nouveaux arrivants et l\'attachement des habitants de longue date.<br>\n<!-- /wp:kubio/text -->\n<!-- /wp:kubio/column -->\n\n<!-- wp:kubio/column {\"kubio\":{\"styleRef\":\"e9QeQr8pFaW\",\"_style\":{\"descendants\":{\"container\":{\"columnWidth\":{\"type\":\"custom\",\"custom\":{\"value\":56.82,\"unit\":\"%\"}}}}},\"hash\":\"PAceVH9P3\",\"style\":{\"descendants\":{\"inner\":{\"border\":{\"top\":{\"radius\":{\"left\":{\"value\":6,\"unit\":\"px\"},\"right\":{\"value\":6,\"unit\":\"px\"}}},\"bottom\":{\"radius\":{\"right\":{\"value\":6,\"unit\":\"px\"},\"left\":{\"value\":6,\"unit\":\"px\"}}}},\"background\":{\"type\":\"image\",\"image\":[{\"source\":{\"type\":\"image\",\"url\":\"http://localhost/wordpress/wp-content/uploads/2025/01/Capture-decran-2025-01-09-152201.png\"},\"position\":{\"x\":0,\"y\":49},\"size\":\"contain\"}]},\"customHeight\":{\"type\":\"min-height\",\"min-height\":{\"value\":500,\"unit\":\"px\"}}}}}}} /-->\n<!-- /wp:kubio/row -->\n<!-- /wp:kubio/section -->\n\n<!-- wp:kubio/section {\"kubio\":{\"styleRef\":\"FiDbteS1a\",\"hash\":\"pcf5GiVQm\",\"style\":{\"descendants\":{\"outer\":{\"background\":{\"color\":\"#f2f2f2\"},\"separators\":{\"top\":{\"enabled\":false,\"height\":{\"value\":10,\"unit\":\"%\"}},\"bottom\":{\"enabled\":false,\"height\":{\"value\":10,\"unit\":\"%\"}}}}}}},\"attrs\":{\"name\":\"Content 1\"},\"anchor\":\"content-1\",\"kubioAI\":{\"meta\":{\"category\":\"content\",\"cloudPresetId\":1167}}} -->\n<!-- wp:kubio/row {\"kubio\":{\"styleRef\":\"p1Xphzuf8N\",\"props\":{\"layout\":{\"itemsPerRow\":2,\"custom\":[{\"type\":\"custom\",\"custom\":{\"value\":33.33,\"unit\":\"%\"}},{\"type\":\"custom\",\"custom\":{\"value\":66.66,\"unit\":\"%\"}}],\"equalHeight\":true,\"equalWidth\":false,\"verticalGap\":3,\"horizontalGap\":3},\"media\":{\"mobile\":{\"layout\":{\"horizontalGap\":3}}}},\"hash\":\"tM3Hj-_tTS\"}} -->\n<!-- wp:kubio/column {\"kubio\":{\"styleRef\":\"N9EJCUO1Pi\",\"_style\":{\"descendants\":{\"container\":{\"columnWidth\":{\"typ