ns...\"},\"icon\":{\"name\":\"icons8-line-awesome/envelope\"},\"lock\":{\"remove\":false,\"edit\":false,\"move\":false}} /-->\n\n<!-- wp:kubio/social-icon {\"kubio\":{\"styleRef\":\"bpCXRIPeQEg\",\"hash\":\"XCconT_tZ\"},\"link\":{\"typeOpenLink\":\"newWindow\",\"value\":\"https://www.youtube.com/user/carcassonneville\"},\"icon\":{\"name\":\"icons8-line-awesome/youtube-play\"},\"lock\":{\"remove\":false,\"edit\":false,\"move\":false}} /-->\n\n<!-- wp:kubio/social-icon {\"kubio\":{\"styleRef\":\"HZ1fCCQIDek\",\"hash\":\"F6dsAIzXS\"},\"link\":{\"typeOpenLink\":\"newWindow\",\"value\":\"https://www.instagram.com/villecarcassonne/?hl=fr\"},\"icon\":{\"name\":\"icons8-line-awesome/instagram\"},\"lock\":{\"remove\":false,\"edit\":false,\"move\":false}} /-->\n<!-- /wp:kubio/social-icons -->\n<!-- /wp:kubio/column -->\n\n<!-- wp:kubio/column {\"kubio\":{\"styleRef\":\"d7gISChHeUI\",\"style\":{\"descendants\":{\"inner\":{\"textAlign\":\"left\",\"media\":{\"mobile\":{\"textAlign\":\"center\"}}}}},\"props\":{\"layout\":{\"verticalAlign\":\"center\",\"vSpace\":{\"value\":10,\"unit\":\"px\"}}},\"_style\":{\"descendants\":{\"container\":{\"columnWidth\":{\"type\":\"flexgrow\",\"custom\":{\"value\":\"\",\"unit\":\"%\"}}}}},\"hash\":\"tIZ4kMdf4Jm\"},\"lock\":{\"remove\":true}} -->\n<!-- wp:kubio/text {\"kubio\":{\"styleRef\":\"ZMaFBdCxr0B\",\"hash\":\"RNRZRZNic\",\"style\":{\"descendants\":{\"text\":{\"typography\":{\"color\":\"rgba(var(--kubio-color-5),1)\"}}}}},\"lock\":{\"remove\":false,\"edit\":false,\"move\":false}} -->\nCarcassonne est une commune de l’Aude, située dans la région Occitanie, au cœur du sud de la France. Elle se trouve à proximité de Limoux, Trèbes, Lézignan-Corbières, et Castelnaudary.\n<!-- /wp:kubio/text -->\n\n<!-- wp:kubio/text {\"kubio\":{\"styleRef\":\"EG52YCP54n\",\"hash\":\"6lSpSMUOZ\",\"style\":{\"descendants\":{\"text\":{\"typography\":{\"color\":\"rgba(var(--kubio-color-5),1)\"}}}}},\"lock\":{\"remove\":false,\"edit\":false,\"move\":false}} -->\n32 Rue Aimé Ramond, 11000 Carcassonne\n<!-- /wp:kubio/text -->\n\n<!-- wp:kubio/copyright {\"kubio\":{\"styleRef\":\"KpgSw42QFJ9\",\"hash\":\"dwxXGQObYyA\",\"style\":{\"descendants\":{\"container\":{\"typography\":{\"size\":{\"value\":14,\"unit\":\"px\"},\"color\":\"rgba(var(--kubio-color-6-variant-3),1)\"}}}}},\"lock\":{\"remove\":true,\"edit\":true,\"move\":true}} -->\n© {year} {site-name}. Created for free using WordPress and <a target=\"_blank\" href=\"https://kubiobuilder.com/\" rel=\"noopener\">Kubio</a>\n<!-- /wp:kubio/copyright -->\n<!-- /wp:kubio/column -->\n<!-- /wp:kubio/row -->\n<!-- /wp:kubio/section -->\n\n<!-- wp:kubio/section {\"kubio\":{\"styleRef\":\"6IRpr1H52y\",\"hash\":\"0Wg0iiUbko\",\"style\":{\"descendants\":{\"outer\":{\"background\":{\"color\":\"rgba(var(--kubio-color-4),1)\"},\"customHeight\":{\"type\":\"min-height\"},\"padding\":{\"bottom\":{\"value\":0,\"unit\":\"px\"},\"top\":{\"value\":0,\"unit\":\"px\"}},\"margin\":{\"top\":{\"value\":-15,\"unit\":\"px\"},\"bottom\":{\"value\":-15,\"unit\":\"px\"},\"left\":{\"value\":-15,\"unit\":\"px\"},\"right\":{\"value\":-15,\"unit\":\"px\"}}},\"inner\":{\"margin\":{\"top\":{\"value\":0}}}}}},\"lock\":{\"remove\":false,\"edit\":false,\"move\":false}} -->\n<!-- wp:kubio/row {\"kubio\":{\"styleRef\":\"HIQtZq3rX\",\"props\":{\"layout\":{\"itemsPerRow\":1,\"custom\":[{\"type\":\"custom\",\"custom\":{\"value\":100,\"unit\":\"%\"}}],\"equalHeight\":true,\"equalWidth\":false}},\"hash\":\"GhRfeZHPA9\"},\"lock\":{\"remove\":false,\"edit\":false,\"move\":false}} -->\n<!-- wp:kubio/column {\"kubio\":{\"styleRef\":\"albFNeiMNr\",\"_style\":{\"descendants\":{\"container\":{\"columnWidth\":{\"type\":\"custom\",\"custom\":{\"value\":100,\"unit\":\"%\"}}}}},\"hash\":\"eaeqP8GU8B\"},\"lock\":{\"remove\":false,\"edit\":false,\"move\":false}} -->\n<!-- wp:kubio/linkgroup {\"kubio\":{\"styleRef\":\"w-8UGr3Ye\",\"hash\":\"1H0JFwtsnq\"},\"lock\":{\"remove\":false,\"edit\":false,\"move\":false}} -->\n<!-- wp:kubio/link {\"ku