(1174, 3, '2025-01-12 01:11:44', '2025-01-12 00:11:44', '<!-- wp:kubio/section {\"kubio\":{\"styleRef\":\"A9O1CGLWQK\",\"hash\":\"47hwCGG5Ez\",\"props\":{\"width\":\"full-width\"},\"style\":{\"descendants\":{\"outer\":{\"padding\":{\"top\":{\"value\":0,\"unit\":\"px\"},\"bottom\":{\"value\":0,\"unit\":\"px\"}}}}}},\"attrs\":{\"name\":\"Section\"},\"anchor\":\"section\"} -->\n<!-- wp:kubio/row {\"kubio\":{\"styleRef\":\"q3SRjtDW0\",\"props\":{\"layout\":{\"itemsPerRow\":1,\"custom\":[{\"type\":\"custom\",\"custom\":{\"value\":100,\"unit\":\"%\"}}],\"equalHeight\":true,\"equalWidth\":false,\"horizontalAlign\":\"center\",\"horizontalGap\":2}},\"hash\":\"cx6wmuppL\"}} -->\n<!-- wp:kubio/column {\"kubio\":{\"styleRef\":\"g2ANeJv_Nh\",\"_style\":{\"descendants\":{\"container\":{\"columnWidth\":{\"type\":\"custom\",\"custom\":{\"value\":94,\"unit\":\"%\"}}}}},\"hash\":\"aMIzSd9L6G\",\"props\":{\"layout\":{\"vSpace\":{\"value\":0,\"unit\":\"px\"}}}}} -->\n<!-- wp:kubio/heading {\"kubio\":{\"styleRef\":\"LNdnzx6pL\",\"style\":{\"descendants\":{\"text\":{\"textAlign\":\"left\"}}},\"props\":{\"level\":3,\"fancy\":{\"fancyRotatingWords\":\"génial\\ngénial\\nimpressionnant\"}},\"hash\":\"asTCm3LaK\"}} -->\n<strong>Chambre de Commerce et d\'Industrie (CCI) : Soutien aux Entreprises Locales</strong>\n<!-- /wp:kubio/heading -->\n\n<!-- wp:kubio/divider {\"kubio\":{\"styleRef\":\"tHsQ5Kx14w\",\"props\":{\"type\":\"line\"},\"style\":{\"descendants\":{\"outer\":{\"padding\":{\"bottom\":{\"value\":\"10\",\"unit\":\"px\"},\"top\":{\"value\":\"10\",\"unit\":\"px\"}},\"textAlign\":\"left\"},\"line\":{\"border\":{\"top\":{\"style\":\"solid\"},\"left\":{\"style\":\"solid\"},\"right\":{\"style\":\"solid\"},\"bottom\":{\"width\":{\"value\":3,\"unit\":\"px\"},\"color\":\"rgba(var(--kubio-color-1),1)\",\"style\":\"solid\"}}},\"inner\":{\"fill\":\"rgba(var(--kubio-color-1),1)\",\"width\":{\"value\":50,\"unit\":\"px\"},\"height\":{\"value\":50,\"unit\":\"px\"},\"margin\":{\"left\":{\"value\":\"10