\"} /-->\n\n<!-- wp:kubio/image-gallery-item {\"kubio\":{\"styleRef\":\"KR8RIkyl_rF\",\"hash\":\"dgVQNCfnoJB\"},\"id\":1266,\"url\":\"http://localhost/wordpress/wp-content/uploads/2025/01/images-2.jpg\"} /-->\n\n<!-- wp:kubio/image-gallery-item {\"kubio\":{\"styleRef\":\"EDmCE-Pn-6_\",\"hash\":\"bJftQ_Yn2XU\"},\"id\":1272,\"url\":\"http://localhost/wordpress/wp-content/uploads/2025/01/unnamed.png\"} /-->\n\n<!-- wp:kubio/image-gallery-item {\"kubio\":{\"styleRef\":\"xfv-8pANBQW\",\"hash\":\"Dc0B4WuEmfS\"},\"id\":1273,\"url\":\"http://localhost/wordpress/wp-content/uploads/2025/01/dsc06048.jpg\"} /-->\n<!-- /wp:kubio/image-gallery -->\n<!-- /wp:kubio/column -->\n<!-- /wp:kubio/row -->\n<!-- /wp:kubio/section -->\n\n<!-- wp:kubio/section {\"kubio\":{\"styleRef\":\"WrMmn1B7Sv\",\"hash\":\"J5OVwQSbpI\",\"style\":{\"descendants\":{\"outer\":{\"background\":{\"color\":\"#f2f2f2\"},\"typography\":{\"holders\":{\"p\":{\"color\":\"rgba(var(--kubio-color-5),1)\"},\"h1\":{\"color\":\"rgba(var(--kubio-color-5),1)\"},\"h2\":{\"color\":\"rgba(var(--kubio-color-5),1)\"},\"h3\":{\"color\":\"rgba(var(--kubio-color-5),1)\"},\"h4\":{\"color\":\"rgba(var(--kubio-color-5),1)\"},\"h5\":{\"color\":\"rgba(var(--kubio-color-5),1)\"},\"h6\":{\"color\":\"rgba(var(--kubio-color-5),1)\"}}},\"separators\":{\"top\":{\"enabled\":false,\"height\":{\"value\":10,\"unit\":\"%\"}},\"bottom\":{\"enabled\":false,\"height\":{\"value\":10,\"unit\":\"%\"}}}}}}},\"attrs\":{\"name\":\"portenarbonnaise\"},\"anchor\":\"portenarbonnaise\",\"kubioAI\":{\"meta\":{\"category\":\"content\",\"cloudPresetId\":805}}} -->\n<!-- wp:kubio/row {\"kubio\":{\"styleRef\":\"kK-BAyGbRW\",\"props\":{\"layout\":{\"itemsPerRow\":2,\"custom\":[{\"type\":\"custom\",\"custom\":{\"value\":33.33,\"unit\":\"%\"}},{\"type\":\"custom\",\"custom\":{\"value\":66.66,\"unit\":\"%\"}}],\"equalHeight\":true,\"equalWidth\":false,\"verticalGap\":3,\"horizontalGap\":3},\"media\":{\"mobile\":{\"layout\":{\"horizontalGap\":3}}}},\"hash\":\"xVcjTTvplD\"}} -->\n<!-- wp:kubio/column {\"kubio\":{\"styleRef\":\"eUxFqO-IBj\",\"_style\":{\"descendants\":{\"container\":{\"columnWidth\":{\"type\":\"custom\",\"custom\":{\"value\":50,\"unit\":\"%\"}}}}},\"hash\":\"qk2fVxvPBM\",\"style\":{\"descendants\":{\"inner\":{\"textAlign\":\"left\"}}},\"props\":{\"layout\":{\"horizontalInnerGap\":3,\"verticalInnerGap\":3,\"verticalAlign\":\"center\",\"vSpace\":{\"value\":40,\"unit\":\"px\"}}}}} -->\n<!-- wp:kubio/heading {\"kubio\":{\"styleRef\":\"fEjpHyoRcE\",\"props\":{\"level\":3,\"fancy\":{\"fancyRotatingWords\":\"awesome\\namazing\\nimpressive\"}},\"hash\":\"GesPu4Lryh\",\"style\":{\"descendants\":{\"text\":{\"typography\":{\"color\":\"rgba(var(--kubio-color-5-variant-5),1)\"}}}}}} -->\nLa&nbsp;Porte Narbonnaise\n<!-- /wp:kubio/heading -->\n\n<!-- wp:kubio/text {\"kubio\":{\"styleRef\":\"He7zWhiEE-s\",\"hash\":\"tb6kr7zMWG\",\"props\":{\"isLead\":false},\"style\":{\"descendants\":{\"text\":{\"typography\":{\"color\":\"rgba(var(--kubio-color-6),1)\"},\"textAlign\":\"justify\"}}}}} -->\nLa majestueuse Porte Narbonnaise, entrée principale de Carcassonne, se distingue par son imposante architecture défensive. Elle offre aux visiteurs un aperçu saisissant de la grandeur médiévale de la cité. Son allure emblématique témoigne de l\'histoire riche et fortifiée de Carcassonne.\n<!-- /wp:kubio/text -->\n<!-- /wp:kubio/column -->\n\n<!-- wp:kubio/column {\"kubio\":{\"styleRef\":\"DN8M7MLsec\",\"_style\":{\"descendants\":{\"container\":{\"columnWidth\":{\"type\":\"custom\",\"custom\":{\"value\":50,\"unit\":\"%\"}}}}},\"hash\":\"v8Yb7cwah\",\"style\":{\"descendants\":{\"inner\":{\"border\":{\"top\":{\"radius\":{\"left\":{\"value\":6,\"unit\":\"px\"},\"right\":{\"value\":6,\"unit\":\"px\"}}},\"bottom\":{\"radius\":{\"right\":{\"value\":6,\"unit\":\"px\"},\"left\":{\"value\":6,\"unit\":\"px\"}}}},\"background\":{\"type\":\"image\",\"image\":[{\"source\":{\"type\":\"image\",\"url\":\"http://localhost/wordpress/wp-content/uploads/2025/01/imagerare.avif\"},\"position\":{\"x\":50,\"y\":50}}]},\"customHeight\":{\"type\":\"min-height\",\"min-height\":{\"value\":500,\"unit\":\"px\"}}}}}}} /-->\n<!-- /wp:kubio/row -->\n<!-- /wp:kubio/section -->', 'Cité médiévale', '', 'publish', 'closed', 'closed', '', 'histoire', '', '', '2025-01-13 14:38:07', '2025-01-13 13:38:07', '', 0, 'http://localhost/wordpress/?page_id=1228', 0, 'page', '', 0),
