"},\"iconName\":\"font-awesome/star\"} /-->\n<!-- /wp:kubio/column -->\n<!-- /wp:kubio/row -->\n<!-- /wp:kubio/section -->\n\n<!-- wp:kubio/section {\"kubio\":{\"styleRef\":\"RHrwpiwy6l\",\"hash\":\"TZ_YzN-Vp1\"},\"attrs\":{\"name\":\"Section 2\"},\"anchor\":\"section-2\"} -->\n<!-- wp:kubio/row {\"kubio\":{\"styleRef\":\"tLDxdPTbh\",\"props\":{\"layout\":{\"itemsPerRow\":1,\"custom\":[{\"type\":\"custom\",\"custom\":{\"value\":100,\"unit\":\"%\"}}],\"equalHeight\":true,\"equalWidth\":false}},\"hash\":\"IZ8MQ7rsie\"}} -->\n<!-- wp:kubio/column {\"kubio\":{\"styleRef\":\"flkLwvgW0q\",\"_style\":{\"descendants\":{\"container\":{\"columnWidth\":{\"type\":\"custom\",\"custom\":{\"value\":50,\"unit\":\"%\"}}}}},\"hash\":\"I_4aq_Awr\"}} -->\n<!-- wp:kubio/image {\"kubio\":{\"styleRef\":\"OPYKzPw9_\",\"hash\":\"qj0xt5Lof\",\"style\":{\"descendants\":{\"image\":{\"border\":{\"top\":{\"radius\":{\"left\":{\"value\":15,\"unit\":\"px\"},\"right\":{\"value\":15,\"unit\":\"px\"}}},\"bottom\":{\"radius\":{\"right\":{\"value\":15,\"unit\":\"px\"},\"left\":{\"value\":15,\"unit\":\"px\"}}}}},\"overlay\":{\"border\":{\"top\":{\"radius\":{\"left\":{\"value\":15,\"unit\":\"px\"},\"right\":{\"value\":15,\"unit\":\"px\"}}},\"bottom\":{\"radius\":{\"right\":{\"value\":15,\"unit\":\"px\"},\"left\":{\"value\":15,\"unit\":\"px\"}}}}}}}},\"url\":\"http://localhost/wordpress/wp-content/uploads/2025/01/Capture-decran-2025-01-12-214828.png\",\"id\":1387,\"sizeSlug\":\"full\"} /-->\n<!-- /wp:kubio/column -->\n\n<!-- wp:kubio/column {\"kubio\":{\"styleRef\":\"puk6NTJbWt\",\"_style\":{\"descendants\":{\"container\":{\"columnWidth\":{\"type\":\"custom\",\"custom\":{\"value\":19,\"unit\":\"%\"}},\"media\":{\"tablet\":{\"columnWidth\":{\"type\":\"custom\",\"custom\":{\"value\":100,\"unit\":\"%\"}}}}}}},\"hash\":\"Qpwi1feDDp\",\"props\":{\"layout\":{\"verticalAlign\":\"center\"}},\"style\":{\"descendants\":{\"inner\":{\"textAlign\":\"left\",\"padding\":{\"right\":{\"value\":40,\"unit\":\"px\"}},\"media